import myPhoto from '../assents/myphoto.jpg';

function Home() {
    return (
        <div>
            <h1>Головна сторінка</h1>
            <p>Ласкаво просимо на мій сайт!</p>
            <img
                src={myPhoto}
                alt="Моє фото"
                style={{ width: '300px', borderRadius: '8px', marginTop: '20px' }}
            />
            
        </div>
    );
}

export default Home;
